  (() => {
    const url = $('Webhook1').item.json.body.conversation.messages[0].attachments[0].data_url;
    // Host publico de Chatwoot, derivado de la config (le saca /api/v1).
    const base = $('Config Chatwoot').item.json.chatwoot_api.replace(/\/api\/v1\/?$/, '');
    // Las URLs del mock de /admin/chatwoot/prueba ya son publicas.
    if (url.includes('/api/chatwoot/')) {
      return url;
    }
    // Chatwoot devuelve el adjunto con su host interno de Easypanel.
    if (url.includes('easypanel.host')) {
      return url.replace(/^https?:\/\/[^/]+/, base);
    }
    if (url.startsWith('http')) {
      return url;
    }
    return base + url;
  })()
}}

